import assert from "node:assert/strict";
import { describe, test } from "node:test";

import { git } from "./lib/git.ts";
import { tempRepo } from "./lib/temp-repo.ts";
import { commentOnly, releases } from "./proto-comments.ts";

const PROTO = "proto/paladin/data/v1/object.proto";
const GO_STUB = "sdk/go/gen/paladin/data/v1/object.pb.go";
const HANDLER = "backend/internal/api/data/v1/objecth/handler.go";

describe("releases", () => {
  const cases: [string, boolean][] = [
    ["feat(api): reword a field's comment", true],
    ["fix(api): reword a field's comment", true],
    ["docs(proto): reword a field's comment", false],
    ["chore(proto): reformat", false],
  ];
  for (const [message, want] of cases) test(message, async () => assert.equal(await releases(message, [PROTO]), want));
});

const BUF_YAML = "version: v2\n";
const proto = (comment: string, fields = "") =>
  `syntax = "proto3";\npackage paladin.data.v1;\n\n// ${comment}\nmessage Object {\n  string name = 1;${fields}\n}\n`;

describe("commentOnly", () => {
  test("refuses a release-cutting commit whose proto change is a comment alone", async () => {
    const repo = await tempRepo();
    try {
      repo.write("proto/buf.yaml", BUF_YAML);
      repo.write(PROTO, proto("An object."));
      const base = await repo.commit("feat(api): objects");

      repo.write(PROTO, proto("An object, as stored."));
      const reworded = await repo.commit("feat(api): say what an object is");
      // As sdk/go/v0.98.0 was cut: a server feature that updated a comment.
      repo.write(PROTO, proto("An object, as stored and listed."));
      repo.write(GO_STUB, "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage datav1 // listed\n");
      repo.write(HANDLER, "package objecth // lists\n");
      const mixed = await repo.commit("feat(api): list objects by name");

      // Not refused: a comment as docs, a field added, and a feature with no
      // proto change at all.
      repo.write(PROTO, proto("An object, once more."));
      await repo.commit("docs(proto): reword the object");
      repo.write(PROTO, proto("An object, once more.", "\n  string etag = 2;"));
      await repo.commit("feat(api): an object's etag");
      repo.write(HANDLER, "package objecth // serves etags\n");
      await repo.commit("feat(api): serve an object's etag");

      const refused = await commentOnly(base, "HEAD", repo.dir);
      assert.deepEqual(
        refused.map((r) => [r.commit, r.subject]),
        [
          [reworded, "feat(api): say what an object is"],
          [mixed, "feat(api): list objects by name"],
        ],
      );
    } finally {
      repo.cleanup();
    }
  });

  test("passes a range with no proto change", async () => {
    const repo = await tempRepo();
    try {
      repo.write(HANDLER, "package objecth\n");
      const base = await repo.commit("feat(api): a handler");
      repo.write(HANDLER, "package objecth // more\n");
      await repo.commit("feat(api): more of it");
      assert.deepEqual(await commentOnly(base, "HEAD", repo.dir), []);
      assert.ok((await git(["rev-parse", "HEAD"], repo.dir)).trim() !== base);
    } finally {
      repo.cleanup();
    }
  });
});
